import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十四卦 歸妹 雷澤歸妹 震上兌下","description":"周易 - 第五十四卦 歸妹 雷澤歸妹 震上兌下","frontmatter":{"title":"第五十四卦 歸妹 雷澤歸妹 震上兌下","description":"周易 - 第五十四卦 歸妹 雷澤歸妹 震上兌下"},"headers":[],"relativePath":"classics/zhouyi/055.md","filePath":"classics/zhouyi/055.md"}'),l={name:"classics/zhouyi/055.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="歸妹" tabindex="-1">歸妹 <a class="header-anchor" href="#歸妹" aria-label="Permalink to “歸妹”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>徵兇，無攸利。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>歸妹，天地之大義也。天地不交，而萬物不興，歸妹人之終始也。說以動，所歸妹也。徵兇，位不當也。無攸利，柔乘剛也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上有雷，歸妹；君子以永終知敝。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>歸妹以娣，跛能履，徵吉。象曰：歸 妹以娣，以恆也。跛能履吉，相承也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>眇能視，利幽人之貞。象曰：利幽人之貞，未變常也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>歸妹以須，反歸以娣。象曰：歸妹以須，未當也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>歸妹愆期，遲歸有時。象曰：愆期之志，有待而行也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。象曰：帝乙歸妹，不如其娣之袂良也。其位在中，以貴行也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>女承筐無實，士刲羊無血，無攸利。象曰：上六無實，承虛筐也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
